        spec_string = ' spec=%r'
        if self._spec_set:
            spec_string = ' spec_set=%r'
        spec_string = spec_string % self._spec_class.__name__
    return "<%s%s%s id='%s'>" % (
        type(self).__name__,
        name_string,
        spec_string,
        id(self)
    )


