                        self._id_cache[attr.value] = node
                        if attr.value == id:
                            result = node
                        elif not node._magic_id_nodes:
                            break
                elif info.isId(attr.name):
                    self._id_cache[attr.value] = node
                    if attr.value == id:
                        result = node
                    elif not node._magic_id_nodes:
                        break
                elif attr._is_id:
                    self._id_cache[attr.value] = node
                    if attr.value == id:
                        result = node
                    elif node._magic_id_nodes == 1:
                        break
        elif node._magic_id_nodes:
            for attr in node.attributes.values():
                if attr._is_id:
                    self._id_cache[attr.value] = node
                    if attr.value == id:
