    r = []
    for cookie in self: r.append(repr(cookie))
    return "<%s[%s]>" % (self.__class__.__name__, ", ".join(r))

def __str__(self):
    r = []
    for cookie in self: r.append(str(cookie))
    return "<%s[%s]>" % (self.__class__.__name__, ", ".join(r))

