    else:
        co = None
    m = self.add_module(fqname)
    m.__file__ = pathname
    if co:
        if self.replace_paths:
            co = self.replace_paths_in_code(co)
        m.__code__ = co
        self.scan_code(co, m)
    self.msgout(2, "load_module ->", m)
    return m

